let quotaNoticeSequence=0,quotaNotices=[];
function quotaNoticeText(raw){const a=normalizeModel(raw);return `${a.name||a.provider}${a.user?' · '+a.user:''}：${a.kind==='expires'?`${a.credits||0} 次重置即将到期`:a.kind==='renews'?`${a.window} 即将重置，已使用 ${Number(a.used||0).toFixed(1)}%`:a.balance?`当前余额 ${a.balance}`:`${a.window||'额度'} 已使用 ${Number(a.used||0).toFixed(1)}%`}${a.resetsAt?' · '+dateText(a.resetsAt):''}`;}
async function refreshQuotaNotices(){if(document.hidden)return;try{const r=await api('subscriptions/alerts?after='+quotaNoticeSequence);quotaNoticeSequence=r.sequence;for(const a of r.alerts||[])quotaNotices.push(a);quotaNotices=quotaNotices.slice(-60);const b=$('#quota-notices');if(b){b.textContent=`提醒${quotaNotices.length?' · '+quotaNotices.length:''}`;b.hidden=!quotaNotices.length;}if(r.alerts?.length)message(quotaNoticeText(r.alerts.at(-1).alert));}catch(e){const b=$('#quota-notices');if(b){b.title='提醒读取失败：'+e.message;}}}
document.addEventListener('DOMContentLoaded',()=>{const b=document.createElement('button');b.id='quota-notices';b.type='button';b.hidden=true;b.onclick=()=>{editor={type:'read-only'};$('#editor-title').textContent='供应商额度提醒';$('#fields').innerHTML=`<div class="panel">${quotaNotices.slice().reverse().map(n=>`<div class="row"><div class="text"><strong>${escape(quotaNoticeText(n.alert))}</strong><p class="caption">${escape(dateText(n.at))}</p></div></div>`).join('')}</div>`;showEditor();$('#save').hidden=true;};$('.toolbar-actions')?.prepend(b);refreshQuotaNotices();setInterval(refreshQuotaNotices,30000);});
const globalNumber=(value,digits=0)=>Number(value||0).toLocaleString('zh-CN',{maximumFractionDigits:digits});
function localLedgerDay(value){const d=new Date(value);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function exchangeRateNote(){const fx=globalData.fx||{};if(!(fx.rate>0))return '人民币汇率暂不可用，费用继续按 USD 显示。';return `人民币换算参考：1 USD ≈ ${Number(fx.rate).toFixed(4)} CNY${fx.at?` · 获取于 ${escape(dateText(fx.at))}`:''}。${fx.stale?'当前使用缓存或离线参考值。':''}`;}
function globalCost(value){const c=globalData?.settings.currency,r=globalData?.fx?.rate;return `${c==='cny'&&r>0?'¥':'$'}${Number((value||0)*(c==='cny'&&r>0?r:1)).toFixed(3)}`;}
function pageSegments(items,current){return `<div class="segments page-segments" role="tablist">${Object.entries(items).map(([id,name])=>`<button type="button" role="tab" data-global-section="${id}" aria-selected="${id===current}" aria-pressed="${id===current}">${name}</button>`).join('')}</div>`;}
function sectionHead(title,note){return `<div class="section-head"><div><h2>${title}</h2><p>${note}</p></div></div>`;}
function settingPanel(title,note,body){return `<section class="settings-panel panel">${sectionHead(title,note)}<div class="form-grid">${body}</div></section>`;}
function settingsForm(body){return `<form id="global-form">${body}<div class="page-save-bar"><span id="global-save-status" class="caption" role="status">修改后保存生效</span><div class="actions">${button('取消修改','','','').replace('data-action=""','data-global="cancel-settings"')}<button type="submit" class="primary">保存设置</button></div></div></form>`;}
function modelChoices(models,current){const choices=[['','自动选择'],['off','关闭'],...(models||[]).map(m=>[m.id,m.name||m.id])];if(current&&!choices.some(([id])=>id===current))choices.push([current,current+'（保留当前设置，未出现在候选中）']);return choices;}
function imageChoice(kind,label,current){const models=kind==='vision'?globalData.visionModels:globalData.drawingModels,unused=globalData[kind==='vision'?'visionUnused':'imageGenUnused'],automatic=globalData[kind==='vision'?'autoVision':'autoDrawer'];return selectField(kind,label,modelChoices(models,current),current)+'<p class="'+(unused?'inline-error':'form-hint')+'">'+(current==='off'?'已关闭。':(unused?'当前设置已失效，运行时将自动选择；原值保留。':'')+'自动候选：'+escape(automatic||'无可用模型'))+'</p>';}

function compactionSettings(s){return settingPanel('对话压缩','模型和供应商独立阈值优先；使用完整窗口仍保留回复 Token 与安全余量。',checkField('fullContext','使用模型完整窗口',s.fullContext)+integerField('compactAt','全局提前压缩阈值（Token）',s.compactAt||0,0,null,'0 使用默认 272K；只对实际窗口更大的模型生效'));}
function connectionSettings(){const s=globalData.settings;return settingsForm(compactionSettings(s)+settingPanel('连接','供鲸Bridge发往供应商的请求使用。供应商和账号的独立代理优先于此处。',proxyFields(s.proxy||'')+text('fetchPrivate','允许下载的内网地址',(s.fetchPrivate||[]).join('\n'),'每行一个：主机名、主机名:端口、IP 或 CIDR 网段。请求或供应商回复里的图片、视频和网页默认只从公网地址下载；只填写你信任的本机或局域网服务。'))+settingPanel('回复与重试','控制网关如何结束重复输出，以及供应商安全审核拒绝后的额外尝试。',checkField('noLoopGuard','允许模型持续输出重复内容（关闭循环保护）',s.noLoopGuard)+field('refusalRetries','安全审核拒绝后重试次数',s.refusalRetries??'','number','留空尝试其他剩余账号或成员；0 不重试')+selectField('codexPredictions','Codex 输入框预测模型',[['','自动：沿用 Codex 当前模型'],['off','关闭预测'],...modelChoices(globalData.models,s.codexPredictions).filter(([id])=>id&&id!=='off')],s.codexPredictions||'')+'<p class="form-hint">预测仅处理 Codex 输入框的辅助请求，不改变对话模型。</p>')+settingPanel('模型名称与费用显示','只改变显示名称和估算费用的币种，不改变模型 ID 或供应商账单。',selectField('currency','估算费用币种',[['usd','美元 USD'],['cny','人民币 CNY']],s.currency||'usd')+checkField('chineseUnits','大数使用万、亿',s.chineseUnits)+checkField('plainNames','模型名称不附加供应商',s.plainNames)+checkField('plainOwnNames','自定义模型名称保持原样',s.plainOwnNames)+checkField('memberModel','路由回复报告实际成员模型',s.memberModel))+`<p class="caption">${exchangeRateNote()}原始用量费用以 USD 保存。</p>`)+uniformPricePanel();}
function searchRows(){const saved=globalData.searches||[],vendors=(globalData.searchVendors||[]).map(normalizeModel),ordered=[...saved.map(a=>vendors.find(v=>v.id===a.vendor)).filter(Boolean),...vendors.filter(v=>!saved.some(a=>a.vendor===v.id))];return ordered.map(v=>{const at=saved.findIndex(x=>x.vendor===v.id),a=saved[at];return `<div class="row search-api-row" data-search-api="${escape(v.id)}"><div class="text"><h3>${escape(v.name)}${a?` <span class="tag">${a.off?'已停用':a.ready?'已启用':'配置不完整'}</span>`:''}</h3><p class="caption">${a?`${escape(a.url||(v.id==='you'&&!a.keySet?'You.com 免费搜索':v.base)||'')} · ${escape(a.keyMasked||'无需密钥')}${a.keySet?' · '+(a.pick==='order'?'顺序使用密钥':'密钥轮流使用'):''}`:'尚未配置'} ${externalLink(v.keysURL||v.keysUrl,'获取密钥')}</p></div><div class="actions"><button type="button" data-global="edit-search" data-id="${escape(v.id)}">${a?'编辑':'添加'}</button>${a?`<button type="button" data-global="switch-search" data-id="${escape(v.id)}" aria-pressed="${!a.off}">${a.off?'启用':'停用'}</button><button type="button" data-global="move-search-up" data-id="${escape(v.id)}" aria-label="上移 ${escape(v.name)}" ${at===0?'disabled':''}>上移</button><button type="button" data-global="move-search-down" data-id="${escape(v.id)}" aria-label="下移 ${escape(v.name)}" ${at===saved.length-1?'disabled':''}>下移</button>${a.canQuota?`<button type="button" data-global="search-quota" data-id="${escape(v.id)}">读取额度</button>`:''}${a.keySet?`<button type="button" data-global="show-search" data-id="${escape(v.id)}">显示密钥</button><button type="button" data-global="copy-search" data-id="${escape(v.id)}">复制密钥</button>`:''}<button type="button" class="danger" data-global="remove-search" data-id="${escape(v.id)}">移除</button>`:''}</div><div class="search-quota-result" data-search-quota="${escape(v.id)}" role="status" hidden></div></div>`;}).join('');}
function searchQuotaResult(result){const rows=(result.keys||[]).map(k=>`<tr><td data-label="密钥">${escape(k.key||'已保存密钥')}</td><td data-label="已用 / 上限">${k.err?escape(k.err):k.known?`${globalNumber(k.used)} / ${k.unlimited?'不限量':globalNumber(k.limit)}`:'未报告'}</td><td data-label="套餐与状态">${escape(k.plan||'未报告')}${k.known&&k.paygoLeft!==undefined?' · 额外额度 '+globalNumber(k.paygoLeft):''}${k.resting?' · '+escape(({'used up':'额度已用完','out of credit':'额度不足','turned away':'密钥被拒绝',refused:'密钥被拒绝','rate limited':'限流'})[k.resting]||'暂时休息')+'，暂停至 '+escape(dateText(k.restUntil)):''}</td></tr>`).join('');return `<div class="table-wrap"><table><thead><tr><th>密钥</th><th>已用 / 上限</th><th>套餐与状态</th></tr></thead><tbody>${rows}</tbody></table></div><p class="caption">额度来自供应商；未知值保持未报告。</p>`;}
function searcherField(){const selected=globalData.settings.searcher||'',choices=[['','自动选择'],['off','关闭模型搜索'],...(globalData.searchers||[]).flatMap(c=>[[c.id,c.name+(c.manualOnly?' · 仅手动':'')],...(c.models||[]).map(m=>[m.id,c.name+' · '+m.name])]),['manual','手动指定 / 保留当前值']],choice=choices.some(([id])=>id===selected)?selected:'manual',why=({gone:'供应商不存在',off:'供应商已停用或未登录',cant:'供应商不支持网页搜索',nomodel:'未找到可用搜索模型',spent:'搜索账号额度已用尽'})[globalData.searcherUnused],failure=normalizeModel(globalData.searcherFailure||{});return selectField('searcherChoice','选择搜索供应商或模型',choices,choice)+field('searcher','搜索供应商或模型 ID',selected,'text','留空自动选择；off 关闭模型搜索')+'<p class="'+(why?'inline-error':'form-hint')+'">'+(why?'当前设置未被使用：'+escape(why)+'。':'')+(selected==='off'?'模型搜索已关闭；已配置的搜索 API 仍可使用。':'当前模型搜索：'+escape(globalData.searcher||'无可用模型')+'；自动候选：'+escape(globalData.autoSearcher||'无可用模型')+'。')+'</p>'+(globalData.searcherFailed?'<p class="inline-error" role="status">最近搜索失败：'+escape(failure.notSearched?'模型没有执行网页搜索':failure.nothingFound?'搜索未找到网页':failure.why||'未成功')+(failure.at?' · '+escape(dateText(failure.at)):'')+'</p>':'');}
