function sideEffortField(kind,label){const s=globalData.settings,levels=globalData[kind+'Efforts']||[],now=globalData[kind+'EffortNow'];return selectField(kind+'Effort',label,sideEffortChoices(levels,s[kind+'Effort']),s[kind+'Effort']||'')+'<p class="form-hint">'+(levels.length?'当前模型可用级别：'+escape(levels.map(sideEffortLabel).join('、'))+'。':'当前模型没有公布推理级别。')+(now?'当前实际级别：'+escape(sideEffortLabel(now))+'。':'')+'运行时按所选模型支持的级别适配。</p>';}
