function privacySettings(){const s=globalData.settings,names={ssn:'美国社会安全号码',passport:'护照号码',iban:'国际银行账号 IBAN',birthday:'生日',mac:'MAC 地址',serial:'设备序列号',home:'用户主目录名称',userhost:'user@host 用户和主机名',ip:'公网 IP 地址',bucket:'云存储桶名称'},kinds=(globalData.redactCategories||[]).map(raw=>{const c=normalizeModel(raw);return checkField('redact-kind-'+c.id,names[c.id]||c.id,s.redactKinds?.[c.id]??c.on);}).join('');return settingsForm(settingPanel('账号与额度读取','这些选择只属于本机，备份和同步不会改变。关闭发现后，鲸Bridge立即忘记此前从外部客户端读取的账号。API Key 供应商仍可用；已保存登录凭据不会删除。',checkField('noAccountDiscovery','关闭账号发现与订阅读取',s.noAccountDiscovery)+(globalData.noAccountsEnv?'<p class="form-hint">当前进程的 MAGPIE_NO_ACCOUNTS 环境变量也已关闭账号发现。</p>':'')+selectField('quotaReads','读取订阅额度与 API 余额',[['','需要时自动读取'],['asked','仅在我点击刷新时读取']],s.quotaReads||''))+settingPanel('发送前脱敏','敏感值替换为占位符发送，供应商回复中的占位符在本机恢复。可信本地供应商可单独豁免。',checkField('redact','保护 API 密钥、令牌、私钥和密码',s.redact)+checkField('redactPersonal','保护邮箱、电话和身份信息',s.redactPersonal)+kinds+'<p class="form-hint">分类开关在个人信息保护开启时生效。路径与地址默认保留，避免改变代码和配置中的精确引用。</p>'+text('redactWords','额外保护的词语',(s.redactWords||[]).join('\n'),'每行一个词语'))+`<section class="panel global-form-panel">${sectionHead('自定义敏感值规则','补充内置规则未覆盖的密钥前缀或 RE2 正则表达式。')}<div id="redact-rules">${(s.redactRules||[]).map(ruleRow).join('')}</div><button type="button" data-global="add-rule">添加规则</button></section>`);}
