 for(const b of root.querySelectorAll('[data-usage-breakdown]'))b.onclick=()=>{usageBreakdown=b.dataset.usageBreakdown;const panel=b.closest('.usage-breakdown-panel');panel.outerHTML=usageShares(usageSummaryData);bindUsageSummary(root);};
 for(const node of root.querySelectorAll('[data-usage-point]')){
  const select=()=>{usagePoint=Number(node.dataset.usagePoint);const panel=node.closest('.usage-trend-panel');panel.outerHTML=usageChart(usageSummaryData.series,usageSummaryData.bucket);decorateSelects();bindUsageSummary(root);};
  node.onclick=select;node.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();root.querySelector(`[data-usage-point="${usagePoint}"]`)?.focus();}};
 }
 const selector=root.querySelector('#usage-trend');if(selector)selector.onchange=e=>{usageTrend=e.target.value;usagePoint=-1;const panel=selector.closest('.usage-trend-panel');panel.outerHTML=usageChart(usageSummaryData.series,usageSummaryData.bucket);decorateSelects();bindUsageSummary(root);};
