function routeNote(c){return [c.free===true?'免费候选':c.routing==='free'?'付费 / 未知价格候选':'',c.barred?'模型已停用':'',c.held?'访问受限':'',c.capped?'达到用量上限 '+c.capped+'%':'',c.noCredits?'不使用付费额度':'',c.turn?'当前轮次':'',c.fallback?'备用候选':'',c.aside?'协议备用':'',c.unlisted?'未列出模型':'',c.fast?'快速模式':'',c.fixed?'固定推理 '+c.fixed:'',c.rest?'暂时休息':'',c.sunk?'限流后排到末尾':''].filter(Boolean).join(' · ')||'可用';}
function routeTable(records){return records?.length?'<section class="panel">'+records.slice().reverse().map(r=>{
const candidates=[...(r.order||[]),...(r.left||[])], rule=r.rule||{}, affinity=r.affinity||{},routingMode=r.group?.routing??candidates[0]?.routing,isFreeFirst=routingMode==='free'||candidates.some(c=>c.routing==='free'||c.free===true);
return '<details class="route-record"><summary><strong>'+escape(r.model)+'</strong> · '+escape(dateText(r.time))+' · '+(r.done?'HTTP '+(r.status||'—'):'处理中')+(r.error?' · '+escape(r.error):'')+'</summary><dl class="request-detail"><dt>供应商 / 实际模型</dt><dd>'+escape(r.provider)+' / '+escape(r.served||r.model)+'</dd><dt>路由方式</dt><dd>'+escape(routingLabel(routingMode,'供应商默认'))+(r.group?' · '+escape(r.group.name||r.group.id):'')+'</dd><dt>首 Token / 总耗时</dt><dd>'+(r.ttft||0)+' / '+(r.ms||0)+' ms</dd><dt>输入与输出总计 / 输出</dt><dd>'+short(r.tokens)+' / '+short(r.out)+'</dd><dt>会话 / 固定账号</dt><dd>'+escape(r.session||'未记录')+' / '+escape(r.pinned||'自动')+'</dd><dt>命中规则</dt><dd>'+escape(rule.name||rule.pattern||rule.kind||rule.id||'无')+'</dd><dt>会话亲和</dt><dd>'+escape(affinity.who||affinity.id||affinity.account||r.group?.affinity||'未固定')+'</dd></dl>'+(r.nested?.length?'<p class="caption">嵌套路径：'+escape(r.nested.map(n=>n.name||n.id||n.group?.name||n.group?.id||'子路由').join(' → '))+'</p>':'')+'<h3>候选与排序</h3>'+(isFreeFirst?'<p class="form-hint" data-free-first-trace>'+escape(freeFirstNote)+'</p>':'')+'<div class="table-wrap"><table><thead><tr><th>顺序</th><th>供应商 / 账号</th><th>模型</th><th>已用额度 / 重置</th><th>状态与原因</th></tr></thead><tbody>'+candidates.map((c,i)=>'<tr><td>'+(i+1)+'</td><td>'+escape(c.name||c.provider)+'<p class="caption">'+escape(c.who||c.id)+'</p></td><td>'+escape(c.model)+'</td><td>'+(c.known?Number(c.used||0).toFixed(1)+'%':'未报告')+'<p class="caption">'+escape((c.renews||[]).map(dateText).join(' · '))+'</p></td><td>'+escape(routeNote(c))+'</td></tr>').join('')+'</tbody></table></div><h3>实际尝试</h3>'+(r.tries?.length?'<div class="table-wrap"><table><thead><tr><th>账号 / 模型</th><th>结果</th><th>首 Token / 总耗时</th><th>排队与恢复</th></tr></thead><tbody>'+r.tries.map(t=>'<tr><td>'+escape(t.id)+'<p class="caption">'+escape(t.served||t.model)+' · '+escape(t.effort||'默认推理')+'</p></td><td>'+(t.done?'HTTP '+(t.status||'—'):'处理中')+'<p class="'+(t.error?'inline-error':'caption')+'">'+escape(t.error||t.fail||t.upstream||'')+'</p></td><td>'+(t.ttft||0)+' / '+(t.ms||0)+' ms</td><td>排队 '+(t.queued||0)+' ms'+(t.again?' · 重试前等待 '+t.again+' ms':'')+(t.reset?'<p class="caption">'+escape(t.reset.who)+' · '+escape(t.reset.text)+'</p>':'')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="empty-inline">尚未尝试。</p>')+'</details>';
}).join('')+'</section>':'<section class="panel"><p class="empty-inline">尚无路由记录。</p></section>';}
function captureGlobalDrafts(){if(tab!=='settings')return;const snapshots=[];for(const f of $('#content').querySelectorAll('form')){if(f.id==='search-edit-form')continue;snapshots.push({id:f.id,dynamic:[...f.querySelectorAll('#redact-rules,#uniform-price-tiers')].map(e=>{const copy=e.cloneNode(true);for(const button of copy.querySelectorAll('button'))button.disabled=false;return {id:e.id,html:copy.innerHTML};}),values:[...f.querySelectorAll('input,select,textarea')].map(i=>({value:i.value,checked:i.checked,type:i.type}))});}if(snapshots.length)globalDrafts.set(globalSection,snapshots);}
function clearGlobalFormDraft(id,section,saved){const remaining=(globalDrafts.get(section)||[]).filter(d=>d.id!==id||JSON.stringify(d)!==JSON.stringify(saved));if(remaining.length)globalDrafts.set(section,remaining);else globalDrafts.delete(section);}
function restoreGlobalDrafts(){for(const d of globalDrafts.get(globalSection)||[]){const f=document.getElementById(d.id);if(!f)continue;for(const block of d.dynamic||[]){const e=f.querySelector('#'+block.id);if(e)e.innerHTML=block.html;}[...f.querySelectorAll('input,select,textarea')].forEach((i,n)=>{const v=d.values[n];if(!v||i.type==='file')return;i.value=v.value;if(i.type==='checkbox')i.checked=v.checked;});}}
