 const personal=root.querySelector('[name=redactPersonal]');if(personal){const update=()=>root.querySelectorAll('[name^="redact-kind-"]').forEach(i=>i.disabled=!personal.checked);personal.addEventListener('change',update);update();}
 const effortSequence={searcher:0,vision:0};
 const updateEffort=async(kind,model)=>{const control=root.querySelector(`[name=${kind}Effort]`);if(!control)return;const sequence=++effortSequence[kind],value=control.value;control.setAttribute('aria-busy','true');try{const levels=model==='off'?[]:await api('tools/efforts?model='+encodeURIComponent(model||''));if(epoch!==renderEpoch||!control.isConnected||sequence!==effortSequence[kind])return;control.innerHTML=sideEffortChoices(levels,value).map(([v,label])=>`<option value="${escape(v)}" ${v===value?'selected':''}>${escape(label)}</option>`).join('');const hint=control.parentElement.querySelector('p.form-hint');if(hint)hint.textContent=levels?.length?'所选模型可用级别：'+levels.map(sideEffortLabel).join('、')+'。修改后保存生效。':'所选模型没有公布推理级别，已保存的选择仍保留。';captureGlobalDrafts();}catch(e){if(epoch===renderEpoch&&control.isConnected)message('推理级别读取失败：'+e.message,true);}finally{if(sequence===effortSequence[kind])control.setAttribute('aria-busy','false');}};
 const searchId=root.querySelector('[name=searcher]'),searchChoice=root.querySelector('[name=searcherChoice]');if(searchId){const update=()=>{let model=searchId.value||globalData.autoSearcher;const choice=(globalData.searchers||[]).find(c=>c.id===model);if(choice?.small)model=choice.id+'/'+choice.small;updateEffort('searcher',model);};searchId.addEventListener('change',update);searchChoice?.addEventListener('change',update);}
